/* CID150's option accessors (g_aeopid records 1234, 1233, 1232: get, set), inline as the ones above; named in v1.17 from
 * the SOPART field each reads (CID150 is a Splice reference to one part of an SO; were func_002562B8..func_00256350). Each setter
 * then calls InvalidateSoAaox on the part's object (HYPOTHESIS: marks its tree dirty). */
extern "C" void InvalidateSoAaox(SO *pso);
inline float GetPartRefRadius(CID150 *p) { return p->psopart->radius; }
inline void SetPartRefRadius(CID150 *p, float g) { p->psopart->radius = g; InvalidateSoAaox(p->pso); }
inline short GetPartRefDamage(CID150 *p) { return p->psopart->damage; }
inline void SetPartRefDamage(CID150 *p, short dhp) { p->psopart->damage = dhp; InvalidateSoAaox(p->pso); }
inline uint GetPartRefZapKinds(CID150 *p) { return p->psopart->zapKindFlags; }
inline void SetPartRefZapKinds(CID150 *p, uint grfzpk) { p->psopart->zapKindFlags = grfzpk; InvalidateSoAaox(p->pso); }

/* SOTREE: a physics tree: SOs connected for collision/physics, solved together; bounds, part list and contact lists.
   Layout from src/game/engine/graphics/pipeline/glob/LoadGlobsetFromBrx__FP7GLOBSETP2SOP18CBinaryInputStream.cpp (3 copies in Lilly ports) */
struct SOTREE
{
      union { qword boundsMin; VECTOR4 vecBoundsMin; }; /* bounding box minimum (VECTOR4: by component, water.cpp) */
      union { qword boundsMax; VECTOR4 vecBoundsMax; }; /* bounding box maximum */
      qword boundsCenter; /* bounding sphere centre */
      float boundsRadius; /* bounding sphere radius */
      DL parts;    /* parts in the tree */
      DLE dleAwake;   /* link in the world's awake-tree list */
      DLE dleAll;   /* link in the list of all trees */
      DLE dleQueue1;   /* link in the first update queue */
      DLE dleQueue2;   /* link in the second update queue */
      SO *root;      /* root object */
      XPLIST *pxplistFirst;   /* first contact list */
      XP *pxpFirst;   /* first contact point */
      XP *firstZapContact; /* first contact that delivers a zap (damage) */
      union
      {
      ulong grf;   /* +0x70 the flag bits below as one doubleword (sensor.cpp and guardbhv.cpp views test them by mask; LASEN's
                      NewTree sets 0x20) */
      struct
      {
      ulong isInFirstQueue : 1; /* in the first queue */
               ulong isInSecondQueue : 1; /* in the second queue */
               uint skipsUpdate : 1; /* skip the physics update (uint-typed: GetSoTreeFlag2 reads it as a 32-bit field; the queue bits stay ulong: MarkSoTreeBoundsDirty tests them with ld) */
               ulong wasTouched : 1; /* touched this frame */
               ulong isDone : 1;  /* processed this frame */
               ulong unknownBits70A : 59;
      };
      };
};

/* XPLIST: the contacts between a physics tree and one other object (SOTREE::pxplistFirst chains them). Moved from the
   identical copies in so.cpp, glob.cpp and jt.cpp. */
struct XPLIST
{
      XP *pxpFirst;
      XPLIST *pxplistNext;
      XP **ppxpHead;
      SO *psoOther;
};

/* XF: a transform of an SO's hierarchy: local and world matrix, the actuators that animate it and its parent.
   Layout from src/game/gameplay/player/jt/RebuildJtXmg.cpp (8 copies in Lilly ports) */
struct XF
{
      union
      {
            MATRIX4 localMatrix; /* local matrix */
            MATRIX4Q localMatq;   /* its rows as quadwords (row 3, +0x30: the local position) */
      };
      union
      {
            MATRIX4 worldMatrix; /* world matrix (row 3 = world position, XF+0x70) */
            MATRIX4Q worldMatq;   /* its rows as quadwords */
      };
      float segmentStartTime;
      float segmentEndTime;
      float *timeSource;
      float *speedSource;
      ACT *firstActuator; /* first actuator (ACT) animating this transform */
      int kind;  /* transform kind */
      short role;    /* role of the transform in the model (inferred) */
      short phase;
      OID oid;   /* oid of the transform */
      XF *parent;      /* parent transform */
      int worldStamp;    /* frame stamp of the last world-matrix update */
      union   /* +0xA8: what the transform's role (update mode) attaches */
      {
            XF *reference;   /* the reference transform (the default roles) */
            float arrivalTime;   /* roles 9 and 0x11: the absolute arrival time (ACT8::Update; asega.cpp: blend weight) */
            struct CHAINLINK *plink;   /* a chain role: the chain link (so.cpp UpdateSoChains, xf.cpp UpdateChainLink) */
            struct IKREC *pikrec;   /* the IK role: the IK record (ik.cpp) */
            struct XFMCONSTR *pconstr;   /* role 0xF (constrained): the constraint (constraint.cpp) */
      };
      short stiffness;
      short damping;
      union
      {
            VECTOR4 velocity;
            QWROW velq;   /* the same as a quadword */
      };
      union   /* +0xC0..+0xFF: the segment block, by role and phase */
      {
            struct
            {
                  qword restValue;   /* rest / goal value (act.cpp goalValue) */
                  qword rate;   /* +0xD0 its rate (act.cpp goalVelocity; asega.cpp: a rotation channel's curve word) */
                  qword segmentEndValue;   /* +0xE0 the end value of the current Hermite segment (EvaluateBezierPos: restValue / rate at the start, this / acceleration at the end); xfk 6 keeps its angle here (inferred) */
                  qword acceleration;
            };
            struct   /* phase 1: the cubic (Bezier/Hermite) segment's four control values (act.cpp) */
            {
                  qword segmentStart;
                  qword segmentStartTangent;
                  qword segmentEnd;
                  qword segmentEndTangent;
            };
            qword rotationRows[4];   /* rotation roles: the rows of a rotation basis */
      };
};
typedef char assert_XF_reference[SLY2_OFFSETOF(XF, reference) == 0xA8 ? 1 : -1];
typedef char assert_XF_restValue[SLY2_OFFSETOF(XF, restValue) == 0xC0 ? 1 : -1];
typedef char assert_XF_segmentEndTangent[SLY2_OFFSETOF(XF, segmentEndTangent) == 0xF0 ? 1 : -1];
typedef char assert_XF_size[sizeof(XF) == 0x100 ? 1 : -1];

/* XA: an attachment between two SOs, kept in two lists: the source's and the target's (inferred from the links).
   Layout from src/game/gameplay/player/jt/SetJtState__FP2JT3JTS4JTBS.cpp (4 copies in Lilly ports) */
struct XA
{
      SO *source;   /* the object whose accelerations it supplies (water.cpp: the WATER; slot 71 is called on it) */
      SO *other; /* the other object: the one the accelerations are applied to */
      XA *nextInOther;   /* next record in the other object's list (SO::pxa; water.cpp AddSoXa / RemoveSoXa) */
      XA *nextInSource;   /* next record in the source object's list (WATER::pxaFirst; UpdateWater / UpdateSwXaList). Were
                             pxaNextSource / pxaNextTarget, the other way round from what the code links through them */
};

#endif /* SLY2_SO_H */
